import requests, sys, uuid, json

BASE = '{{TESTVDB_DB_URL}}'
c = 'test_dtype_null_' + uuid.uuid4().hex[:8]

# Test 1: create_collection.vectors.datatype = null
print("=== TEST 1: create_collection.vectors.datatype=null ===")
payload = {
    "vectors": {
        "size": 4,
        "distance": "Cosine",
        "datatype": None
    }
}
r = requests.put(f'{BASE}/collections/{c}', json=payload)
print(f"Status: {r.status_code}, Body: {r.text[:200]}")
if r.status_code == 200:
    print('[DEFECT: ILLEGAL_SUCCESS] create_collection with datatype=null was accepted')
    # Cleanup
    requests.delete(f'{BASE}/collections/{c}')
    sys.exit(1)
else:
    print(f'datatype=null correctly rejected: {r.status_code}')

# Test 2: create_collection.vectors.datatype = "not_a_number"
print("\n=== TEST 2: create_collection.vectors.datatype='not_a_number' ===")
c2 = 'test_dtype_str_' + uuid.uuid4().hex[:8]
payload2 = {
    "vectors": {
        "size": 4,
        "distance": "Cosine",
        "datatype": "not_a_number"
    }
}
r2 = requests.put(f'{BASE}/collections/{c2}', json=payload2)
print(f"Status: {r2.status_code}, Body: {r2.text[:200]}")
if r2.status_code == 200:
    print('[DEFECT: ILLEGAL_SUCCESS] create_collection with datatype="not_a_number" was accepted')
    requests.delete(f'{BASE}/collections/{c2}')
    sys.exit(1)
else:
    print(f'datatype="not_a_number" correctly rejected: {r2.status_code}')

# Test 3: create_collection.vectors.datatype = oversized string
print("\n=== TEST 3: create_collection.vectors.datatype=oversized ===")
c3 = 'test_dtype_big_' + uuid.uuid4().hex[:8]
payload3 = {
    "vectors": {
        "size": 4,
        "distance": "Cosine",
        "datatype": "A" * 100000
    }
}
r3 = requests.put(f'{BASE}/collections/{c3}', json=payload3)
print(f"Status: {r3.status_code}, Body: {r3.text[:200]}")
if r3.status_code == 200:
    print('[DEFECT: ILLEGAL_SUCCESS] create_collection with oversized datatype was accepted')
    requests.delete(f'{BASE}/collections/{c3}')

